```typescript
// data-validation-hook.ts
export interface DataValidationInput {
  filePath: string;
  expectedColumns: string[];
  delimiter?: string;
}

export interface DataValidationOutput {
  isValid: boolean;
  errors: string[];
  rowCount: number;
}

export const validateDataFile = (input: DataValidationInput): DataValidationOutput => {
  const errors: string[] = [];
  let rowCount = 0;

  try {
    const fileContent = Deno.readTextFileSync(input.filePath);
    const lines = fileContent.split('\n').filter(line => line.trim() !== '');
    rowCount = lines.length;

    if (rowCount === 0) {
      errors.push('File is empty');
      return { isValid: false, errors, rowCount };
    }

    const header = lines[0].split(input.delimiter || ',');
    const missingColumns = input.expectedColumns.filter(col => !header.includes(col));
    if (missingColumns.length > 0) {
      errors.push(`Missing columns: ${missingColumns.join(', ')}`);
    }

    if (errors.length === 0) {
      return { isValid: true, errors: [], rowCount };
    }
    return { isValid: false, errors, rowCount };
  } catch (error) {
    errors.push(`Failed to read file: ${error.message}`);
    return { isValid: false, errors, rowCount: 0 };
  }
};
```

This hook validates CSV/TSV files against expected columns and returns structured validation results. It handles file reading errors, empty files, and missing columns with clear error messages. The type-safe interfaces ensure compile-time checks for input/output compatibility with Claude agents.
